<?php require_once __DIR__.'/dbconnect.php';require_once __DIR__.'/../security.php';require_once __DIR__.'/../foundation.php';oecrm_require_admin_login();$companyId=oecrm_current_company_id($conn);$id=(int)($_GET['id']??0);$r=mysqli_fetch_assoc(mysqli_query($conn,'SELECT p.*,f.invoice_number,c.display_name,co.display_name company_name FROM finance_payments p JOIN finance_invoices f ON f.id=p.invoice_id JOIN clients c ON c.id=f.client_id JOIN companies co ON co.id=p.company_id WHERE p.id='.$id.' AND p.company_id='.$companyId));if(!$r)exit('Receipt not found.');?><!doctype html><html><head><style>body{font-family:Arial;padding:40px;color:#303448}.receipt{max-width:650px;margin:auto;border:1px solid #ddd;padding:30px}button{padding:8px 14px}</style></head><body><div class="receipt"><button onclick="print()">Print / PDF</button><h1>Payment Receipt</h1><h3><?php echo oecrm_h($r['company_name']);?></h3><p>Received from: <strong><?php echo oecrm_h($r['display_name']);?></strong></p><p>Invoice: <?php echo oecrm_h($r['invoice_number']);?></p><p>Date: <?php echo date('d M Y',strtotime($r['payment_date']));?></p><h2>Amount: <?php echo number_format($r['amount'],2);?></h2><p>Method: <?php echo ucfirst($r['gateway']);?><br>Reference: <?php echo oecrm_h($r['transaction_reference']);?></p></div></body></html>
